import pytest
from concurrent.futures import ThreadPoolExecutor


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int], workers: int = 4) -> int:
    """Sum of x*x over every element of xs, with the squares computed in
    parallel by a thread pool of `workers` threads.

    The result is exact integer arithmetic, so it is identical for every
    worker count. An empty list gives 0. The input list is not modified.
    Raises ValueError if workers < 1.
    """
    if workers < 1:
        raise ValueError("workers must be >= 1")
    if not xs:
        return 0
    with ThreadPoolExecutor(max_workers=workers) as pool:
        squares = list(pool.map(square, xs))
    return sum(squares)


def test_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_empty() -> None:
    assert sum_squares([]) == 0


def test_single() -> None:
    assert sum_squares([7]) == 49


def test_negatives_and_zero() -> None:
    assert sum_squares([-3, 0, 3]) == 18


def test_big_ints_exact() -> None:
    big = 10**30
    assert sum_squares([big, -big, 1]) == 2 * big * big + 1


def test_does_not_mutate_input() -> None:
    xs = [3, -1, 2]
    sum_squares(xs)
    assert xs == [3, -1, 2]


@pytest.mark.parametrize("workers", [1, 2, 3, 4, 8, 64, 1000])
def test_same_result_at_every_worker_count(workers: int) -> None:
    xs = list(range(-50, 150))
    expected = sum(x * x for x in xs)
    assert sum_squares(xs, workers=workers) == expected


@pytest.mark.parametrize("workers", [1, 2, 5, 16])
def test_more_workers_than_elements(workers: int) -> None:
    assert sum_squares([2, 3], workers=workers) == 13
    assert sum_squares([], workers=workers) == 0


def test_large_input_matches_serial() -> None:
    xs = [(i * 7919) % 1009 - 500 for i in range(5000)]
    expected = sum(square(x) for x in xs)
    results = {sum_squares(xs, workers=w) for w in (1, 2, 3, 7, 32)}
    assert results == {expected}


def test_default_workers_matches() -> None:
    xs = [5, -4, 3]
    assert sum_squares(xs) == sum_squares(xs, workers=1) == 50


@pytest.mark.parametrize("workers", [0, -1, -10])
def test_invalid_workers_raises(workers: int) -> None:
    with pytest.raises(ValueError):
        sum_squares([1, 2, 3], workers=workers)

